// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IVcAndDiscloseCircuitVerifier} from "../interfaces/IVcAndDiscloseCircuitVerifier.sol";
import {CircuitConstants} from "../constants/CircuitConstants.sol";
import {Formatter} from "./Formatter.sol";

/**
 * @title CircuitAttributeHandler Library
 * @notice Provides functions for extracting and formatting passport attributes from a byte array.
 * @dev Utilizes the Formatter library for converting and formatting specific fields.
 */
library CircuitAttributeHandler {

    /**
     * @dev Reverts when the provided character codes array does not contain enough data to extract an attribute.
     */
    error INSUFFICIENT_CHARCODE_LEN();

    // Define constant start and end positions for each attribute
    uint256 private constant ISSUING_STATE_START = 2;
    uint256 private constant ISSUING_STATE_END = 4;

    uint256 private constant NAME_START = 5;
    uint256 private constant NAME_END = 43;

    uint256 private constant PASSPORT_NUMBER_START = 44;
    uint256 private constant PASSPORT_NUMBER_END = 52;

    uint256 private constant NATIONALITY_START = 54;
    uint256 private constant NATIONALITY_END = 56;

    uint256 private constant DATE_OF_BIRTH_START = 57;
    uint256 private constant DATE_OF_BIRTH_END = 62;

    uint256 private constant GENDER_START = 64;
    uint256 private constant GENDER_END = 64;

    uint256 private constant EXPIRY_DATE_START = 65;
    uint256 private constant EXPIRY_DATE_END = 70;

    uint256 private constant OLDER_THAN_START = 88;
    uint256 private constant OLDER_THAN_END = 89;

    uint256 private constant OFAC_START = 90;
    uint256 private constant OFAC_END = 92;

    /**
     * @notice Retrieves the issuing state from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return A string representing the issuing state.
     */
    function getIssuingState(bytes memory charcodes) internal pure returns (string memory) {
        return extractStringAttribute(charcodes, ISSUING_STATE_START, ISSUING_STATE_END);
    }

    /**
     * @notice Retrieves and formats the name from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return A string array with the formatted name parts.
     */
    function getName(bytes memory charcodes) internal pure returns (string[] memory) {
        return Formatter.formatName(extractStringAttribute(charcodes, NAME_START, NAME_END));
    }

    /**
     * @notice Retrieves the passport number from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return The passport number as a string.
     */
    function getPassportNumber(bytes memory charcodes) internal pure returns (string memory) {
        return extractStringAttribute(charcodes, PASSPORT_NUMBER_START, PASSPORT_NUMBER_END);
    }

    /**
     * @notice Retrieves the nationality from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return The nationality as a string.
     */
    function getNationality(bytes memory charcodes) internal pure returns (string memory) {
        return extractStringAttribute(charcodes, NATIONALITY_START, NATIONALITY_END);
    }

    /**
     * @notice Retrieves and formats the date of birth from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return The formatted date of birth as a string.
     */
    function getDateOfBirth(bytes memory charcodes) internal pure returns (string memory) {
        return Formatter.formatDate(extractStringAttribute(charcodes, DATE_OF_BIRTH_START, DATE_OF_BIRTH_END));
    }

    /**
     * @notice Retrieves the gender from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return The gender as a string.
     */
    function getGender(bytes memory charcodes) internal pure returns (string memory) {
        return extractStringAttribute(charcodes, GENDER_START, GENDER_END);
    }

    /**
     * @notice Retrieves and formats the passport expiry date from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return The formatted passport expiry date as a string.
     */
    function getExpiryDate(bytes memory charcodes) internal pure returns (string memory) {
        return Formatter.formatDate(extractStringAttribute(charcodes, EXPIRY_DATE_START, EXPIRY_DATE_END));
    }

    /**
     * @notice Retrieves the 'older than' age attribute from the encoded attribute byte array.
     * @dev Converts two consecutive numeric ASCII characters to a uint256.
     * @param charcodes The byte array containing passport attribute data.
     * @return The extracted age as a uint256.
     */
    function getOlderThan(bytes memory charcodes) internal pure returns (uint256) {
        return Formatter.numAsciiToUint(uint8(charcodes[OLDER_THAN_START])) * 10
            + Formatter.numAsciiToUint(uint8(charcodes[OLDER_THAN_START + 1]));
    }

    /**
     * @notice Retrieves the passport number OFAC status from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return The OFAC status for passport number check as a uint256.
     */
    function getPassportNoOfac(bytes memory charcodes) internal pure returns (uint256) {
        return uint8(charcodes[OFAC_START]);
    }

    /**
     * @notice Retrieves the name and date of birth OFAC status from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return The OFAC status for name and DOB check as a uint256.
     */
    function getNameAndDobOfac(bytes memory charcodes) internal pure returns (uint256) {
        return uint8(charcodes[OFAC_START + 1]);
    }

    /**
     * @notice Retrieves the name and year of birth OFAC status from the encoded attribute byte array.
     * @param charcodes The byte array containing passport attribute data.
     * @return The OFAC status for name and YOB check as a uint256.
     */
    function getNameAndYobOfac(bytes memory charcodes) internal pure returns (uint256) {
        return uint8(charcodes[OFAC_START + 2]);
    }

    /**
     * @notice Performs selective OFAC checks based on provided flags.
     * @param charcodes The byte array containing passport attribute data.
     * @param checkPassportNo Whether to check the passport number OFAC status.
     * @param checkNameAndDob Whether to check the name and date of birth OFAC status.
     * @param checkNameAndYob Whether to check the name and year of birth OFAC status.
     * @return True if all enabled checks pass (equal 1), false if any enabled check fails.
     * @dev Checks are only performed for flags that are set to true. If a flag is false,
     * that particular check is considered to have passed regardless of its actual value.
     */
    function compareOfac(
        bytes memory charcodes,
        bool checkPassportNo,
        bool checkNameAndDob,
        bool checkNameAndYob
    ) internal pure returns (bool) {
        return (!checkPassportNo || getPassportNoOfac(charcodes) == 1) &&
               (!checkNameAndDob || getNameAndDobOfac(charcodes) == 1) &&
               (!checkNameAndYob || getNameAndYobOfac(charcodes) == 1);
    }

    /**
     * @notice Compares the extracted 'older than' value with a provided threshold.
     * @param charcodes The byte array containing passport attribute data.
     * @param olderThan The threshold value to compare against.
     * @return True if the extracted age is greater than or equal to the threshold, false otherwise.
     */
    function compareOlderThan(
        bytes memory charcodes,
        uint256 olderThan
    ) internal pure returns (bool) {
        return getOlderThan(charcodes) >= olderThan;
    }

    /**
     * @notice Extracts a substring from a specified range in the byte array.
     * @dev Reverts with INSUFFICIENT_CHARCODE_LEN if the byte array's length is insufficient.
     * @param charcodes The byte array containing the encoded passport attribute.
     * @param start The starting index (inclusive) of the attribute in the byte array.
     * @param end The ending index (inclusive) of the attribute in the byte array.
     * @return The extracted attribute as a string.
     */
    function extractStringAttribute(bytes memory charcodes, uint256 start, uint256 end) internal pure returns (string memory) {
        if (charcodes.length <= end) {
            revert INSUFFICIENT_CHARCODE_LEN();
        }
        bytes memory attributeBytes = new bytes(end - start + 1);
        for (uint256 i = start; i <= end; i++) {
            attributeBytes[i - start] = charcodes[i];
        }
        return string(attributeBytes);
    }

}

contracts/libraries/Formatter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title Formatter Library
 * @notice A library providing utility functions to format names, dates, and encode data.
 */
library Formatter {
    error InvalidDateLength();
    error InvalidAsciiCode();
    error InvalidYearRange();
    error InvalidMonthRange();
    error InvalidDayRange();
    error InvalidFieldElement();
    error InvalidDateDigit();

    uint256 constant MAX_FORBIDDEN_COUNTRIES_LIST_LENGTH = 40;
    uint256 constant SNARK_SCALAR_FIELD = 21888242871839275222246405745257275088548364400416034343698204186575808495617;

    /**
     * @notice Formats a full name string into first name(s) and last name.
     * @dev The input is expected to contain a last name, followed by a "<<" separator and then first name(s).
     *      The returned array contains the first names at index 0 and the last name at index 1.
     * @param input The input string structured as "lastName<<firstName(s)".
     * @return names An array of two strings: [firstName(s), lastName].
     */
    function formatName(
        string memory input
    ) internal pure returns (string[] memory) {
        bytes memory inputBytes = bytes(input);
        bytes memory firstNameBytes;
        bytes memory lastNameBytes;
        string[] memory names = new string[](2);

        uint i = 0;
        // Extract last name
        while (i < inputBytes.length && inputBytes[i] != "<") {
            lastNameBytes = abi.encodePacked(lastNameBytes, inputBytes[i]);
            i++;
        }

        // Skip the separator "<<".
        i += 2;

        // Extract first names.
        while (i < inputBytes.length) {
            if (inputBytes[i] == "<") {
                if (i + 1 < inputBytes.length && inputBytes[i + 1] == "<") {
                    break;
                }
                firstNameBytes = abi.encodePacked(firstNameBytes, " ");
            } else {
                firstNameBytes = abi.encodePacked(
                    firstNameBytes,
                    inputBytes[i]
                );
            }
            i++;
        }

        names[0] = string(firstNameBytes);
        names[1] = string(lastNameBytes);
        return names;
    }

    /**
     * @notice Formats a compact date string into a human-readable date.
     * @dev Expects the input date string to have exactly 6 characters in YYMMDD format.
     *      Returns the date in "DD-MM-YY" format.
     * @param date A string representing the date in YYMMDD format.
     * @return A formatted date string in the format "DD-MM-YY".
     */
    function formatDate(
        string memory date
    ) internal pure returns (string memory) {
        bytes memory dateBytes = bytes(date);
        if (dateBytes.length != 6) {
            revert InvalidDateLength();
        }

        if (dateBytes[2] > '1' || (dateBytes[2] == '1' && dateBytes[3] > '2')) {
            revert InvalidMonthRange();
        }

        if (dateBytes[4] > '3' || (dateBytes[4] == '3' && dateBytes[5] > '1')) {
            revert InvalidDayRange();
        }

        for (uint i = 0; i < 6; i++) {
            if (dateBytes[i] < '0' || dateBytes[i] > '9') {
                revert InvalidAsciiCode();
            }
        }

        string memory year = substring(date, 0, 2);
        string memory month = substring(date, 2, 4);
        string memory day = substring(date, 4, 6);

        return string(abi.encodePacked(day, "-", month, "-", year));
    }

    /**
     * @notice Converts an ASCII numeral code to its corresponding unsigned integer.
     * @dev The input must represent an ASCII code for digits (0-9), i.e. between 48 and 57.
     *      Reverts with InvalidAsciiCode if the input is out of range.
     * @param numAscii The ASCII code of a digit character.
     * @return The numeric value (0-9) corresponding to the ASCII code.
     */
    function numAsciiToUint(uint256 numAscii) internal pure returns (uint256) {
        if (numAscii < 48 || numAscii > 57) {
            revert InvalidAsciiCode();
        }
        return (numAscii - 48);
    }

    /**
     * @notice Converts an array of three field elements into a bytes representation.
     * @dev Each element is converted into a specific number of bytes: 31, 31, and 31 respectively.
     * @param publicSignals An array of three unsigned integers representing field elements.
     * @return bytesArray A bytes array of total length 93 that encodes the three field elements.
     */
    function fieldElementsToBytes(
        uint256[3] memory publicSignals
    ) internal pure returns (bytes memory) {
        if (
            publicSignals[0] >= SNARK_SCALAR_FIELD ||
            publicSignals[1] >= SNARK_SCALAR_FIELD ||
            publicSignals[2] >= SNARK_SCALAR_FIELD
        ) {
            revert InvalidFieldElement();
        }
        uint8[3] memory bytesCount = [31, 31, 31];
        bytes memory bytesArray = new bytes(93);

        uint256 index = 0;
        for (uint256 i = 0; i < 3; i++) {
            uint256 element = publicSignals[i];
            for (uint8 j = 0; j < bytesCount[i]; j++) {
                bytesArray[index++] = bytes1(uint8(element & 0xff));
                element = element >> 8;
            }
        }
        return bytesArray;
    }

    /**
     * @notice Extracts forbidden country codes from a packed uint256.
     * @dev Each forbidden country is represented by 3 bytes in the packed data.
     *      The function extracts up to MAX_FORBIDDEN_COUNTRIES_LIST_LENGTH forbidden countries.
     * @param publicSignals A packed uint256 containing encoded forbidden country data.
     * @return forbiddenCountries An array of strings representing the forbidden country codes.
     */
    function extractForbiddenCountriesFromPacked(
        uint256[4] memory publicSignals
    )
        internal
        pure
        returns (
            string[MAX_FORBIDDEN_COUNTRIES_LIST_LENGTH] memory forbiddenCountries
        )
    {
        for (uint256 i = 0; i < 4; i++) {
            if (publicSignals[i] >= SNARK_SCALAR_FIELD) {
                revert InvalidFieldElement();
            }
        }

        for (uint256 j = 0; j < MAX_FORBIDDEN_COUNTRIES_LIST_LENGTH; j++) {
            uint256 byteIndex = j * 3;

            if (byteIndex + 2 < 32) {
                uint256 shift = byteIndex * 8;
                uint256 mask = 0xFFFFFF;
                uint256 packedData = (publicSignals[0] >> shift) & mask;
                forbiddenCountries[j] = string(abi.encodePacked(uint24(packedData)));
            } else if (byteIndex < 32) {
                uint256 bytesFrom0 = 32 - byteIndex;
                uint256 bytesTo1 = 3 - bytesFrom0;

                uint256 shift0 = byteIndex * 8;
                uint256 mask0 = (1 << (bytesFrom0 * 8)) - 1;
                uint256 part0 = (publicSignals[0] >> shift0) & mask0;

                uint256 shift1 = 0;
                uint256 mask1 = (1 << (bytesTo1 * 8)) - 1;
                uint256 part1 = (publicSignals[1] >> shift1) & mask1;

                uint256 combined = (part1 << (bytesFrom0 * 8)) | part0;
                forbiddenCountries[j] = string(abi.encodePacked(uint24(combined)));
            } else {
                uint256 byteIndexIn1 = byteIndex - 32;
                uint256 shift = byteIndexIn1 * 8;
                uint256 mask = 0xFFFFFF;
                uint256 packedData = (publicSignals[1] >> shift) & mask;
                forbiddenCountries[j] = string(abi.encodePacked(uint24(packedData)));
            }
        }

        return forbiddenCountries;

    }

    /**
     * @notice Converts an array of 6 numerical values representing a date into a Unix timestamp.
     * @dev Each element in the dateNum array is taken modulo 10, converted to its ASCII digit, 
     *      and concatenated to form a date string in YYMMDD format. This string is then converted 
     *      into a Unix timestamp using dateToUnixTimestamp.
     * @param dateNum An array of 6 unsigned integers representing a date in YYMMDD format.
     * @return timestamp The Unix timestamp corresponding to the provided date.
     */
    function proofDateToUnixTimestamp(
        uint256[6] memory dateNum
    ) internal pure returns (uint256) {
        for (uint256 i = 0; i < 6; i++) {
        if (dateNum[i] > 9) {
            revert InvalidDateDigit();
            }
        }
        string memory date = "";
        for (uint256 i = 0; i < 6; i++) {
            date = string(
                abi.encodePacked(date, bytes1(uint8(48 + (dateNum[i] % 10))))
            );
        }
        uint256 currentTimestamp = dateToUnixTimestamp(date);
        return currentTimestamp;
    }

    /**
     * @notice Converts a date string in YYMMDD format into a Unix timestamp.
     * @dev Parses the date string by extracting year, month, and day components using substring,
     *      converts each component to an integer, and then computes the timestamp via toTimestamp.
     *      Reverts if the input string is not exactly 6 characters long.
     * @param date A 6-character string representing the date in YYMMDD format.
     * @return timestamp The Unix timestamp corresponding to the input date.
     */
    function dateToUnixTimestamp(
        string memory date
    ) internal pure returns (uint256) {
        bytes memory dateBytes = bytes(date);
        if (dateBytes.length != 6) {
            revert InvalidDateLength();
        }

        if (dateBytes[2] > '1' || (dateBytes[2] == '1' && dateBytes[3] > '2')) {
            revert InvalidMonthRange();
        }

        if (dateBytes[4] > '3' || (dateBytes[4] == '3' && dateBytes[5] > '1')) {
            revert InvalidDayRange();
        }

        for (uint i = 0; i < 6; i++) {
            if (dateBytes[i] < '0' || dateBytes[i] > '9') {
                revert InvalidAsciiCode();
            }
        }

        uint256 year = parseDatePart(substring(date, 0, 2)) + 2000;
        uint256 month = parseDatePart(substring(date, 2, 4));
        uint256 day = parseDatePart(substring(date, 4, 6));

        return toTimestamp(year, month, day);
    }

    /**
     * @notice Extracts a substring from a given string.
     * @dev Returns the substring from startIndex (inclusive) to endIndex (exclusive).
     * @param str The input string.
     * @param startIndex The starting index of the substring (inclusive).
     * @param endIndex The ending index of the substring (exclusive).
     * @return The resulting substring.
     */
    function substring(
        string memory str,
        uint startIndex,
        uint endIndex
    ) internal pure returns (string memory) {
        bytes memory strBytes = bytes(str);
        bytes memory result = new bytes(endIndex - startIndex);

        for (uint i = startIndex; i < endIndex; i++) {
            result[i - startIndex] = strBytes[i];
        }

        return string(result);
    }

    /**
     * @notice Parses a numeric string and returns its unsigned integer representation.
     * @dev Assumes the input string contains only numeric characters.
     * @param value The string representing a number.
     * @return result The parsed unsigned integer.
     */
    function parseDatePart(string memory value) internal pure returns (uint) {
        bytes memory tempEmptyStringTest = bytes(value);
        if (tempEmptyStringTest.length == 0) {
            return 0;
        }

        uint digit;
        uint result;
        for (uint i = 0; i < tempEmptyStringTest.length; i++) {
            if (uint8(tempEmptyStringTest[i]) < 48 || uint8(tempEmptyStringTest[i]) > 57) {
                revert InvalidAsciiCode();
            }
            digit = uint8(tempEmptyStringTest[i]) - 48;
            result = result * 10 + digit;
        }
        return result;
    }

    /**
     * @notice Converts a specific date into a Unix timestamp.
     * @dev Calculates the timestamp by summing the number of days for years, months, and days since January 1, 1970.
     *      Takes leap years into account during the calculation.
     * @param year The full year (e.g., 2023).
     * @param month The month (1-12).
     * @param day The day of the month.
     * @return timestamp The Unix timestamp corresponding to the given date.
     */
    function toTimestamp(
        uint256 year,
        uint256 month,
        uint256 day
    ) internal pure returns (uint timestamp) {
        uint16 i;

        if (year < 1970 || year > 2100) {
            revert InvalidYearRange();
        }

        if (month < 1 || month > 12) {
            revert InvalidMonthRange();
        }

        // Year.
        for (i = 1970; i < year; i++) {
            if (isLeapYear(i)) {
                timestamp += 366 days;
            } else {
                timestamp += 365 days;
            }
        }

        // Month.
        uint8[12] memory monthDayCounts;
        monthDayCounts[0] = 31;
        if (isLeapYear(year)) {
            monthDayCounts[1] = 29;
        } else {
            monthDayCounts[1] = 28;
        }
        monthDayCounts[2] = 31;
        monthDayCounts[3] = 30;
        monthDayCounts[4] = 31;
        monthDayCounts[5] = 30;
        monthDayCounts[6] = 31;
        monthDayCounts[7] = 31;
        monthDayCounts[8] = 30;
        monthDayCounts[9] = 31;
        monthDayCounts[10] = 30;
        monthDayCounts[11] = 31;

        if (day < 1 || day > monthDayCounts[month - 1]) {
            revert InvalidDayRange();
        }

        for (i = 1; i < month; i++) {
            timestamp += monthDayCounts[i - 1] * 1 days;
        }

        // Day.
        timestamp += (day - 1) * 1 days;

        return timestamp;
    }

    /**
     * @notice Checks whether a given year is a leap year.
     * @param year The year to check.
     * @return True if the year is a leap year, otherwise false.
     */
    function isLeapYear(uint256 year) internal pure returns (bool) {
        if (year < 1970 || year > 2100) {
            revert InvalidYearRange();
        }

        if (year % 4 != 0) {
            return false;
        } else if (year % 100 != 0) {
            return true;
        } else if (year % 400 != 0) {
            return false;
        } else {
            return true;
        }
    }

}

